solution:
String reponseLaPlusRapide() throws Exception {
    try (var scope = new StructuredTaskScope.ShutdownOnSuccess<String>()) {
        scope.fork(() -> interroger("serveur-A"));
        scope.fork(() -> interroger("serveur-B"));
        scope.join();
        return scope.result();
    }
}
